#!/usr/bin/env node
// Drift check for plugins/withReleaseSigning.js: confirms the live,
// gitignored android/app/build.gradle and android/build.gradle actually
// contain what the plugin's own transforms inject — not just "the marker is
// somewhere in the file."
//
// Why this needs to exist at all: android/ is regenerated by `expo prebuild`
// and gitignored, so there's no committed copy to `git diff` against. And the
// plugin's own `// @generated` marker means a plain (non-clean) `expo
// prebuild` skips re-applying an already-present block — so after editing
// this plugin, the live files have to be hand-patched to match (a `--clean`
// prebuild would do it automatically, but this project has other
// hand-maintained native/ edits that don't survive `--clean`; see
// docs/HANDOFF.md). Hand-patching is exactly the kind of step that silently
// drifts from the source of truth over time.
//
// FIRST VERSION OF THIS SCRIPT WAS WRONG, on purpose kept here as a warning:
// it called `patchAppBuildGradle(live) === live` a clean bill of health. That
// re-run hits the SAME marker short-circuit the real patch does — the check
// was blind to a file carrying a STALE block (old injected text, marker
// still present, which is exactly what a hand-patch gone wrong looks like)
// and would only ever catch a block that's completely ABSENT. Caught by the
// Mommy Redesign session testing it against a deliberately-staled file
// rather than trusting it. Fixed by asserting the exact injected TEXT is
// present, not by re-invoking the patch.
//
// Run after any edit to withReleaseSigning.js and after hand-patching
// android/ to match: `node scripts/verify-release-signing.js`

const fs = require("fs");
const path = require("path");
const {
  APP_SIGNING_BLOCK,
  APP_BUILDTYPE_LINE,
  ROOT_GUARD_BLOCK,
} = require("../plugins/withReleaseSigning.js");

const ROOT = path.join(__dirname, "..");
const APP_GRADLE = path.join(ROOT, "android/app/build.gradle");
const ROOT_GRADLE = path.join(ROOT, "android/build.gradle");

let failed = false;

function checkContains(fileLabel, filePath, checks) {
  if (!fs.existsSync(filePath)) {
    console.log(`  skip: ${fileLabel} — ${path.relative(ROOT, filePath)} does not exist (no prebuild yet?)`);
    return;
  }
  const live = fs.readFileSync(filePath, "utf8");
  for (const { label, marker, block } of checks) {
    if (live.includes(block)) {
      console.log(`  ok:   ${fileLabel} — ${label} matches exactly`);
    } else if (marker && live.includes(marker)) {
      failed = true;
      console.log(`  FAIL: ${fileLabel} — ${label}: STALE — marker is present but the injected text no longer matches the plugin`);
    } else {
      failed = true;
      console.log(`  FAIL: ${fileLabel} — ${label}: ABSENT — the plugin never patched this file`);
    }
  }
}

console.log("Verifying android/ contains exactly what plugins/withReleaseSigning.js injects...");
checkContains("android/app/build.gradle", APP_GRADLE, [
  { label: "release signingConfig block", marker: "// @generated withReleaseSigning", block: APP_SIGNING_BLOCK },
  { label: "buildTypes.release signingConfig line", marker: null, block: APP_BUILDTYPE_LINE },
]);
checkContains("android/build.gradle", ROOT_GRADLE, [
  { label: "taskGraph release guard", marker: "// @generated withReleaseSigning-guard", block: ROOT_GUARD_BLOCK },
]);

if (failed) {
  console.log(
    "\nDrift detected. Either hand-patch android/ to match plugins/withReleaseSigning.js exactly, " +
      "or force a full regeneration:\n  npx expo prebuild --platform android --clean\n" +
      "(expensive here — this project has other hand-maintained native/ edits that don't survive " +
      "--clean; see docs/HANDOFF.md — so reapply those too if you go this route).",
  );
  process.exit(1);
} else {
  console.log("\nNo drift.");
}
